extends Node
class_name MobileUILayout

const CONFIG_PATH := "res://data/mobile/mobile_ui.json"

var config: Dictionary = {}

func _ready() -> void:
    _load_config()

func layout_root(control: Control) -> void:
    if control == null:
        return

    var viewport_size := control.get_viewport_rect().size
    var ref = config.get("reference_size", [1280, 720])
    var ref_size := Vector2(float(ref[0]), float(ref[1]))

    var scale_x := viewport_size.x / maxf(ref_size.x, 1.0)
    var scale_y := viewport_size.y / maxf(ref_size.y, 1.0)
    var uniform := minf(scale_x, scale_y)
    uniform = clampf(
        uniform,
        float(config.get("min_scale", 0.78)),
        float(config.get("max_scale", 1.30))
    )

    control.scale = Vector2.ONE * uniform

func safe_rect(viewport: Viewport) -> Rect2:
    var visible := viewport.get_visible_rect()
    var margin := float(config.get("safe_margin_px", 18.0))
    return Rect2(
        visible.position + Vector2(margin, margin),
        visible.size - Vector2(margin * 2.0, margin * 2.0)
    )

func camera_drag_sensitivity() -> float:
    return float(config.get("camera_drag_sensitivity", 0.0042))

func _load_config() -> void:
    if not FileAccess.file_exists(CONFIG_PATH):
        return
    var f := FileAccess.open(CONFIG_PATH, FileAccess.READ)
    if f == null:
        return
    var parsed = JSON.parse_string(f.get_as_text())
    if typeof(parsed) == TYPE_DICTIONARY:
        config = parsed

extends Control

signal vector_changed(value)

@export var radius: float = 72.0
@export var deadzone: float = 0.12

var pointer_id: int = -1
var center: Vector2 = Vector2.ZERO
var value: Vector2 = Vector2.ZERO

@onready var knob: Control = get_node_or_null("Knob") as Control

func _ready() -> void:
    mouse_filter = Control.MOUSE_FILTER_STOP
    clip_contents = false
    center = size * 0.5
    _apply_visual(Vector2.ZERO)

func _gui_input(event: InputEvent) -> void:
    if event is InputEventScreenTouch:
        _handle_touch(event)
        return
    if event is InputEventScreenDrag:
        _handle_drag(event)

func _handle_touch(event: InputEventScreenTouch) -> void:
    if event.pressed and pointer_id < 0:
        pointer_id = event.index
        _update_value(event.position)
        accept_event()
        return
    if not event.pressed and event.index == pointer_id:
        pointer_id = -1
        set_value(Vector2.ZERO)
        accept_event()

func _handle_drag(event: InputEventScreenDrag) -> void:
    if event.index != pointer_id:
        return
    _update_value(event.position)
    accept_event()

func _update_value(local_position: Vector2) -> void:
    var delta: Vector2 = local_position - center
    var safe_radius: float = maxf(radius, 1.0)
    var normalized: Vector2 = delta / safe_radius
    if normalized.length_squared() > 1.0:
        normalized = normalized.normalized()
    if normalized.length() < deadzone:
        normalized = Vector2.ZERO
    set_value(normalized)

func set_value(new_value: Vector2) -> void:
    value = new_value.limit_length(1.0)
    _apply_visual(value)
    vector_changed.emit(value)

func _apply_visual(input_value: Vector2) -> void:
    if not is_instance_valid(knob):
        return
    knob.position = center + input_value * radius - knob.size * 0.5

extends Control
class_name PhoneJobsPanel

var job_system = null
var visible_requested := false
var offer_buttons: Array[Button] = []

@onready var title_label: Label = $Panel/Margin/VBox/Title
@onready var offers_box: VBoxContainer = $Panel/Margin/VBox/Offers
@onready var status_label: Label = $Panel/Margin/VBox/Status

func configure(system) -> void:
    job_system = system
    if job_system != null:
        job_system.offer_selected.connect(_on_offer_selected)
        job_system.job_completed.connect(_on_job_completed)
        job_system.job_rejected.connect(_on_job_rejected)
    refresh()

func toggle_phone() -> void:
    visible_requested = not visible_requested
    visible = visible_requested
    if visible:
        refresh()

func refresh() -> void:
    if offers_box == null:
        return

    for child in offers_box.get_children():
        child.queue_free()
    offer_buttons.clear()

    if job_system == null:
        status_label.text = "الخدمة غير متاحة"
        return

    var offers = job_system.available_offers(GameState.current_district)
    if offers.is_empty():
        status_label.text = "ما فماش خدمة متاحة توا"
        return

    status_label.text = "اختار خدمة"
    for offer in offers:
        var button := Button.new()
        var job_id := str(offer.get("id",""))
        button.text = "%s — %.1f د.ت" % [
            str(offer.get("label_ar", job_id)),
            float(offer.get("pay", 0.0))
        ]
        button.pressed.connect(_select_offer.bind(job_id))
        offers_box.add_child(button)
        offer_buttons.append(button)

func _select_offer(job_id: String) -> void:
    if job_system != null:
        job_system.select_offer(job_id)
        refresh()

func _on_offer_selected(_job_id: String, label_ar: String) -> void:
    status_label.text = "قبلت: " + label_ar

func _on_job_completed(_job_id: String, pay: float) -> void:
    status_label.text = "ربحت %.1f د.ت" % pay
    refresh()

func _on_job_rejected(_job_id: String, reason: String) -> void:
    match reason:
        "outside_work_hours":
            status_label.text = "الخدمة مسكرة توا"
        "low_energy":
            status_label.text = "طاقة غير كافية"
        _:
            status_label.text = "ما نجمتش تقبل الخدمة"

extends CharacterBody3D
class_name ArcadeVehicle

signal driver_entered(driver: PlayerController)
signal driver_exited(driver: PlayerController)
signal fuel_empty(vehicle_id: String)

@export var vehicle_id := "vehicle"
@export var display_name := "سيارة"
@export var max_speed := 22.0
@export var max_reverse_speed := 7.0
@export var acceleration := 8.5
@export var reverse_acceleration := 5.5
@export var braking := 18.0
@export var rolling_resistance := 2.2
@export var aerodynamic_drag := 0.018
@export var steering_speed := 1.65
@export var high_speed_steering_factor := 0.38
@export var lateral_grip := 8.0
@export var fuel_burn_idle_per_sec := 0.012
@export var fuel_burn_load_per_sec := 0.16

@onready var seat: Marker3D = $DriverSeat
@onready var exit_point: Marker3D = $ExitPoint

var driver: PlayerController = null
var speed := 0.0
var odometer_m := 0.0
var trip_distance_m := 0.0
var _fuel_empty_emitted := false
var _last_position := Vector3.ZERO

func _ready() -> void:
    _last_position = global_position

func _physics_process(delta: float) -> void:
    if driver == null:
        velocity = velocity.move_toward(Vector3.ZERO, rolling_resistance * delta)
        if velocity.length_squared() > 0.0001:
            move_and_slide()
            _track_distance()
        else:
            velocity = Vector3.ZERO
        return

    var throttle := Input.get_axis("move_back", "move_forward")
    var steer := Input.get_axis("move_right", "move_left")
    var has_fuel := GameState.fuel > 0.01

    _update_longitudinal_speed(throttle, has_fuel, delta)
    _update_steering(steer, delta)
    _update_motion(delta)
    _burn_fuel(throttle, has_fuel, delta)

    if not has_fuel and not _fuel_empty_emitted:
        _fuel_empty_emitted = true
        fuel_empty.emit(vehicle_id)
    elif has_fuel:
        _fuel_empty_emitted = false

    driver.global_position = seat.global_position
    driver.global_rotation.y = global_rotation.y

    if Input.is_action_just_pressed("interact") and absf(speed) <= 1.5:
        exit_vehicle()

func _update_longitudinal_speed(throttle: float, has_fuel: bool, delta: float) -> void:
    var target_speed := 0.0
    var response := rolling_resistance

    if has_fuel and throttle > 0.01:
        target_speed = throttle * max_speed
        response = acceleration
    elif has_fuel and throttle < -0.01:
        target_speed = throttle * max_reverse_speed
        response = reverse_acceleration
    elif absf(speed) > 0.01:
        response = rolling_resistance + absf(speed) * absf(speed) * aerodynamic_drag

    if signf(target_speed) != signf(speed) and absf(target_speed) > 0.01 and absf(speed) > 0.25:
        response = braking
        target_speed = 0.0

    speed = move_toward(speed, target_speed, response * delta)
    if absf(speed) < 0.02:
        speed = 0.0

func _update_steering(steer: float, delta: float) -> void:
    if absf(steer) <= 0.01 or absf(speed) <= 0.08:
        return
    var speed_ratio := clampf(absf(speed) / maxf(max_speed, 0.01), 0.0, 1.0)
    var steering_factor := lerpf(1.0, high_speed_steering_factor, speed_ratio)
    var direction_sign := signf(speed)
    rotation.y += steer * steering_speed * steering_factor * direction_sign * delta

func _update_motion(delta: float) -> void:
    var forward := -global_transform.basis.z
    var desired_velocity := forward * speed
    var grip_alpha := clampf(lateral_grip * delta, 0.0, 1.0)
    velocity.x = lerpf(velocity.x, desired_velocity.x, grip_alpha)
    velocity.z = lerpf(velocity.z, desired_velocity.z, grip_alpha)
    velocity.y = 0.0
    move_and_slide()
    _track_distance()

func _burn_fuel(throttle: float, has_fuel: bool, delta: float) -> void:
    if not has_fuel:
        return
    var load := clampf(absf(throttle), 0.0, 1.0)
    var speed_load := clampf(absf(speed) / maxf(max_speed, 0.01), 0.0, 1.0)
    var burn_rate := fuel_burn_idle_per_sec + fuel_burn_load_per_sec * load * (0.45 + 0.55 * speed_load)
    GameState.set_stat("fuel", GameState.fuel - burn_rate * delta)

func _track_distance() -> void:
    var travelled := global_position.distance_to(_last_position)
    if travelled > 0.0 and travelled < 25.0:
        odometer_m += travelled
        trip_distance_m += travelled
    _last_position = global_position

func reset_trip_meter() -> void:
    trip_distance_m = 0.0
    _last_position = global_position

func enter_vehicle(p: PlayerController) -> void:
    if driver != null:
        return
    driver = p
    GameState.current_vehicle_id = vehicle_id
    p.set_control_enabled(false)
    p.visible = false
    driver_entered.emit(p)

func exit_vehicle() -> void:
    if driver == null or absf(speed) > 1.5:
        return
    var p := driver
    driver = null
    GameState.current_vehicle_id = ""
    p.global_position = exit_point.global_position
    p.visible = true
    p.set_control_enabled(true)
    driver_exited.emit(p)

func serialize_runtime() -> Dictionary:
    return {
        "position": [global_position.x, global_position.y, global_position.z],
        "rotation": [global_rotation.x, global_rotation.y, global_rotation.z],
        "speed": speed,
        "odometer_m": odometer_m,
        "trip_distance_m": trip_distance_m
    }

func restore_runtime(data: Dictionary) -> void:
    var position_value = data.get("position", [])
    if _is_vec3_array(position_value):
        global_position = _safe_vec3(position_value, global_position, 10000.0)

    var rotation_value = data.get("rotation", [])
    if _is_vec3_array(rotation_value):
        global_rotation = _safe_vec3(rotation_value, global_rotation, TAU * 8.0)

    var restored_speed := float(data.get("speed", 0.0))
    if is_nan(restored_speed) or is_inf(restored_speed):
        restored_speed = 0.0
    speed = clampf(restored_speed, -max_reverse_speed, max_speed)
    odometer_m = _safe_nonnegative_stat(data.get("odometer_m", odometer_m), 100000000.0)
    trip_distance_m = _safe_nonnegative_stat(data.get("trip_distance_m", trip_distance_m), 1000000.0)
    velocity = Vector3.ZERO
    _last_position = global_position

func _safe_nonnegative_stat(value, maximum: float) -> float:
    var parsed := float(value)
    if is_nan(parsed) or is_inf(parsed):
        return 0.0
    return clampf(parsed, 0.0, maximum)

func _is_vec3_array(value) -> bool:
    return typeof(value) == TYPE_ARRAY and value.size() == 3

func _safe_vec3(value: Array, fallback: Vector3, limit: float) -> Vector3:
    if value.size() != 3:
        return fallback
    var x := float(value[0])
    var y := float(value[1])
    var z := float(value[2])
    if is_nan(x) or is_nan(y) or is_nan(z) or is_inf(x) or is_inf(y) or is_inf(z):
        return fallback
    return Vector3(
        clampf(x, -limit, limit),
        clampf(y, -limit, limit),
        clampf(z, -limit, limit)
    )
